import Link from "next/link";
import { SITE, TOOL_SEO } from "../../lib/seo";
import "./sitemap.css";

// A human-friendly list of every page. The XML sitemap for search engines is
// generated by app/sitemap.js and served at /sitemap.xml.
export const metadata = {
  title: "Sitemap",
  description: `Every page and tool on ${SITE.name}, listed in one place.`,
  alternates: { canonical: "/sitemap" },
};

export default function SitemapPage() {
  const tools = Object.values(TOOL_SEO);

  return (
    <>
      <div className="page-title">
        <h1>Sitemap</h1>
        <p className="muted">
          Every page on {SITE.name}. The machine-readable sitemap for search engines is at{" "}
          <a className="sitemap-xml-link" href="/sitemap.xml">
            /sitemap.xml
          </a>
          .
        </p>
      </div>

      <div className="card">
        <h2>Main pages</h2>
        <ul className="sitemap-list">
          <li>
            <Link href="/">Home</Link>
            <span className="muted"> - all ten tools at a glance</span>
          </li>
          <li>
            <Link href="/sitemap">Sitemap</Link>
            <span className="muted"> - this page</span>
          </li>
        </ul>

        <h2>Tools</h2>
        <ul className="sitemap-list">
          {tools.map((tool) => (
            <li key={tool.path}>
              <Link href={tool.path}>{tool.name}</Link>
              <span className="muted"> - {tool.title}</span>
            </li>
          ))}
        </ul>
      </div>
    </>
  );
}
